(()=>{const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');if(reduced.matches||!('IntersectionObserver' in window)||!Element.prototype.animate)return;const running=new Set();const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;observer.unobserve(entry.target);if(reduced.matches)return;const a=entry.target.animate([{opacity:.25,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'cubic-bezier(.2,.7,.2,1)'});running.add(a);a.onfinish=()=>running.delete(a);});},{threshold:.08});document.querySelectorAll('.welcome>div,.scripture,.leadership>div,.update-grid>*,.visit>div').forEach(el=>observer.observe(el));reduced.addEventListener('change',e=>{if(e.matches){observer.disconnect();running.forEach(a=>a.cancel());running.clear();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false');}});})();
